import { Group, Mesh, PlaneGeometry, BoxGeometry } from 'three/webgpu';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const { Group: CGroup } = ctx.THREE;

  // Root container
  const root = new CGroup();

  // ---------- Backdrop Gradient Plane ----------
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  // vertical gradient using visualSpec.gradientStops (fallback)
  const gradientStops = (config.visualSpec?.gradientStops ||
    [{ at: 0, hex: '#1a1a22' }, { at: 1, hex: '#121218' }]);
  const topColor = color(gradientStops[0].hex);
  const bottomColor = color(gradientStops[gradientStops.length - 1].hex);
  backdropMat.colorNode = mix(bottomColor, topColor, uv().y);
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---------- Kicker Text ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const kickerItem = items.find(i => i.role === 'kicker') || items[0];
  if (kickerItem) {
    const kicker = ctx.fontAtlas.createText(kickerItem.text, {
      fontSize: kickerItem.typography?.fontSize ?? 9,
      color: '#e8ecf2',
      align: 'center',
      letterSpacingPx: (kickerItem.typography?.letterSpacing ?? 0) * 10,
    });
    kicker.position.set(0, 0.3, 0);
    root.add(kicker);
  }

  // ---------- Tile Grid ----------
  const tileGroup = new CGroup();
  const tileW = 1.0;
  const tileH = 0.62;
  const gap = 0.25;
  const cols = 3;
  const rows = 2;
  const startX = -(cols * tileW + (cols - 1) * gap) / 2 + tileW / 2;
  const startY = -(rows * tileH + (rows - 1) * gap) / 2 + tileH / 2;

  // Prepare material for tiles
  const tileMaterial = new MeshStandardNodeMaterial();
  const gradTop = color('#1a1a22');
  const gradBottom = color('#121218');
  tileMaterial.colorNode = mix(gradBottom, gradTop, uv().y);
  tileMaterial.metalness = 0.5;
  tileMaterial.roughness = 0.55;
  tileMaterial.clearcoat = 0.2;
  tileMaterial.side = ctx.THREE.DoubleSide;

  const tileGeoms = [];
  const tileMeshes = [];

  // Map brand-mark items to tiles (skip kicker)
  const brandItems = items.filter(i => i.role !== 'kicker');
  let brandIndex = 0;

  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      const x = startX + col * (tileW + gap);
      const y = startY + row * (tileH + gap);
      const tile = new Mesh(new PlaneGeometry(tileW, tileH), tileMaterial.clone());
      tile.position.set(x, y, 0);
      tile.userData.handlers = {};

      // Text for this tile
      const txtItem = brandItems[brandIndex];
      if (txtItem) {
        const txt = ctx.fontAtlas.createText(txtItem.text, {
          fontSize: txtItem.typography?.fontSize ?? 13,
          color: '#e8ecf2',
          align: 'center',
          letterSpacingPx: (txtItem.typography?.letterSpacing ?? 0) * 10,
        });
        // default opacity 0.78
        txt.traverse(child => {
          if (child.isMesh && child.material) {
            child.material.transparent = true;
            child.material.opacity = 0.78;
          }
        });
        txt.position.set(0, 0, 0.001);
        tile.add(txt);
        tile.userData._textObject = txt;
      }

      // Hover interaction
      const hoverTimeline = gsap.timeline({ paused: true });
      hoverTimeline.to(tile.position, {
        z: 0.05,
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      });
      if (txtItem) {
        const txtObj = tile.userData._textObject;
        hoverTimeline.to(txtObj.traverse.bind(txtObj, child => {
          if (child.isMesh && child.material) child.material.opacity = 1.0;
        }), {
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        }, 0);
      }
      tile.userData.handlers.hoverEnter = () => hoverTimeline.play();
      tile.userData.handlers.hoverLeave = () => hoverTimeline.reverse();

      // Staggered entrance animation
      const enterTimeline = gsap.from(tile.position, {
        y: tile.position.y + 0.2,
        opacity: 0,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        delay: (row * cols + col) * 0.08,
      });
      tile.userData._enterTimeline = enterTimeline;

      tileGroup.add(tile);
      tileGeoms.push(tile.geometry);
      tileMeshes.push(tile);
      brandIndex = (brandIndex + 1) % brandItems.length;
    }
  }

  root.add(tileGroup);

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    // Dispose geometries & materials
    tileMeshes.forEach(m => {
      if (m.geometry) m.geometry.dispose();
      if (m.material) m.material.dispose();
      if (m.userData._enterTimeline) m.userData._enterTimeline.kill();
    });
    if (backdrop.geometry) backdrop.geometry.dispose();
    if (backdrop.material) backdrop.material.dispose();
    // Kill any gsap timelines stored on root
    gsap.globalTimeline.clear();
  };

  return root;
}
